-- Server-only, rolling checkout attempt limits. Hashes are HMACs generated by
-- the storefront server; raw customer phones and IP addresses are not stored.

CREATE TABLE IF NOT EXISTS storefront.storefront_checkout_attempts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  phone_hash TEXT NOT NULL CHECK (phone_hash ~ '^[0-9a-f]{64}$'),
  ip_hash TEXT NOT NULL CHECK (ip_hash ~ '^[0-9a-f]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_storefront_checkout_attempts_phone_date
  ON storefront.storefront_checkout_attempts (phone_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_storefront_checkout_attempts_ip_date
  ON storefront.storefront_checkout_attempts (ip_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_storefront_checkout_attempts_created_at
  ON storefront.storefront_checkout_attempts (created_at);

ALTER TABLE storefront.storefront_checkout_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON storefront.storefront_checkout_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON storefront.storefront_checkout_attempts TO service_role;

CREATE OR REPLACE FUNCTION storefront.consume_storefront_checkout_attempt(
  p_phone_hash TEXT,
  p_ip_hash TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, storefront
AS $$
DECLARE
  v_phone_lock BIGINT;
  v_ip_lock BIGINT;
  v_phone_count INTEGER;
  v_ip_count INTEGER;
BEGIN
  IF p_phone_hash IS NULL OR p_phone_hash !~ '^[0-9a-f]{64}$'
     OR p_ip_hash IS NULL OR p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Checkout could not be verified.';
  END IF;

  v_phone_lock := hashtextextended('phone:' || p_phone_hash, 0);
  v_ip_lock := hashtextextended('ip:' || p_ip_hash, 0);
  IF v_phone_lock < v_ip_lock THEN
    PERFORM pg_advisory_xact_lock(v_phone_lock);
    PERFORM pg_advisory_xact_lock(v_ip_lock);
  ELSE
    PERFORM pg_advisory_xact_lock(v_ip_lock);
    PERFORM pg_advisory_xact_lock(v_phone_lock);
  END IF;

  DELETE FROM storefront.storefront_checkout_attempts
  WHERE created_at < now() - INTERVAL '2 days';

  SELECT count(*) INTO v_phone_count
  FROM storefront.storefront_checkout_attempts
  WHERE phone_hash = p_phone_hash
    AND created_at >= now() - INTERVAL '1 hour';

  SELECT count(*) INTO v_ip_count
  FROM storefront.storefront_checkout_attempts
  WHERE ip_hash = p_ip_hash
    AND created_at >= now() - INTERVAL '1 hour';

  IF v_phone_count >= 5 OR v_ip_count >= 20 THEN
    RAISE EXCEPTION 'Too many checkout attempts. Please try again later.';
  END IF;

  INSERT INTO storefront.storefront_checkout_attempts (phone_hash, ip_hash)
  VALUES (p_phone_hash, p_ip_hash);

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION storefront.consume_storefront_checkout_attempt(TEXT, TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION storefront.consume_storefront_checkout_attempt(TEXT, TEXT)
  TO service_role;

CREATE TABLE IF NOT EXISTS storefront.storefront_quote_attempts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ip_hash TEXT NOT NULL CHECK (ip_hash ~ '^[0-9a-f]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_storefront_quote_attempts_ip_date
  ON storefront.storefront_quote_attempts (ip_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_storefront_quote_attempts_created_at
  ON storefront.storefront_quote_attempts (created_at);

ALTER TABLE storefront.storefront_quote_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE storefront.storefront_quote_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON TABLE storefront.storefront_quote_attempts TO service_role;

CREATE OR REPLACE FUNCTION storefront.consume_storefront_quote_attempt(
  p_ip_hash TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, storefront
AS $$
DECLARE
  v_count INTEGER;
  v_lock BIGINT;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Checkout quote could not be verified.';
  END IF;

  v_lock := hashtextextended('quote:' || p_ip_hash, 0);
  PERFORM pg_advisory_xact_lock(v_lock);

  DELETE FROM storefront.storefront_quote_attempts
  WHERE created_at < now() - INTERVAL '2 days';

  SELECT count(*) INTO v_count
  FROM storefront.storefront_quote_attempts
  WHERE ip_hash = p_ip_hash
    AND created_at >= now() - INTERVAL '1 hour';

  IF v_count >= 120 THEN
    RAISE EXCEPTION 'Too many quote requests. Please try again later.';
  END IF;

  INSERT INTO storefront.storefront_quote_attempts (ip_hash)
  VALUES (p_ip_hash);

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION storefront.consume_storefront_quote_attempt(TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION storefront.consume_storefront_quote_attempt(TEXT)
  TO service_role;

