  ip_hash TEXT NOT NULL CHECK (ip_hash ~ '^[0-9a-f]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_storefront_tracking_attempts_ip_date
  ON storefront.storefront_tracking_attempts (ip_hash, created_at DESC);
