ALTER TABLE storefront.storefront_tracking_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE storefront.storefront_tracking_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON TABLE storefront.storefront_tracking_attempts TO service_role;

CREATE OR REPLACE FUNCTION storefront.consume_storefront_tracking_attempt(
  p_ip_hash TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, storefront
AS $$
DECLARE
  v_count INTEGER;
  v_lock BIGINT;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Order tracking could not be verified.';
  END IF;

  v_lock := hashtextextended('tracking:' || p_ip_hash, 0);
  PERFORM pg_advisory_xact_lock(v_lock);

  DELETE FROM storefront.storefront_tracking_attempts
  WHERE created_at < now() - INTERVAL '2 days';

  SELECT count(*) INTO v_count
  FROM storefront.storefront_tracking_attempts
  WHERE ip_hash = p_ip_hash
    AND created_at >= now() - INTERVAL '1 hour';

  IF v_count >= 30 THEN
    RAISE EXCEPTION 'Too many tracking attempts. Please try again later.';
  END IF;

  INSERT INTO storefront.storefront_tracking_attempts (ip_hash)
  VALUES (p_ip_hash);

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION storefront.consume_storefront_tracking_attempt(TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION storefront.consume_storefront_tracking_attempt(TEXT)
  TO service_role;

